# --------------------------------------------------------------------------- #
# Modelo de dados
# --------------------------------------------------------------------------- #
@dataclass
class Story:
    persona: str = "usuário"
    action: str = "utilizar a funcionalidade"
    benefit: str = "atingir seu objetivo"
    criteria: list[str] = field(default_factory=list)
    title: str = "Funcionalidade"


# --------------------------------------------------------------------------- #
# Parser (motor baseado em regras)
# --------------------------------------------------------------------------- #
STORY_RE = re.compile(
    r"como\s+(?:um|uma|o|a)?\s*(?P<persona>.+?)[,\n]\s*"
    r"(?:eu\s+)?(?:quero|gostaria de|desejo|preciso)\s+(?P<action>.+?)"
    r"(?:[,\n]\s*(?:para que|para|a fim de)\s+(?P<benefit>.+?))?(?:\.|\n|$)",
    re.IGNORECASE | re.DOTALL,
)
BULLET_RE = re.compile(r"^\s*(?:[-*•]|\d+[.)]|CA\d*[:.-]?)\s*(.+)$", re.IGNORECASE)


def _clean(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip(" .,;:")


def parse_story(raw: str) -> Story:
    story = Story()
    m = STORY_RE.search(raw)
    if m:
        story.persona = _clean(m.group("persona"))
        story.action = _clean(m.group("action"))
        if m.group("benefit"):
            story.benefit = _clean(m.group("benefit"))

    # Critérios: linhas com marcadores ou após "critérios de aceitação"
    lines = raw.splitlines()
    in_criteria = False
    for line in lines:
        low = line.lower()
        if "critério" in low or "criterio" in low or "regra" in low:
            in_criteria = True
            continue
        b = BULLET_RE.match(line)
        if b:
            story.criteria.append(_clean(b.group(1)))
        elif in_criteria and line.strip():
            story.criteria.append(_clean(line))

    # Fallback: frases do texto
    if not story.criteria:
        sentences = [s for s in re.split(r"(?<=[.!?])\s+", raw) if len(s.split()) > 3]
        story.criteria = [_clean(s) for s in sentences if not STORY_RE.match(s)][:6]
    if not story.criteria:
        story.criteria = [f"O sistema deve permitir {story.action}"]

    story.title = story.action[:1].upper() + story.action[1:]
    return story


NEGATIVE_HINTS = ("inválid", "erro", "não deve", "bloque", "negad", "falha", "obrigat", "vazio")


def is_negative(c: str) -> bool:
    return any(h in c.lower() for h in NEGATIVE_HINTS)


def criterion_to_given_when_then(c: str, story: Story) -> tuple[str, str, str]:
    """Divide um critério em contexto/ação/resultado de forma heurística."""
    parts = re.split(r"\b(?:quando|ao|se)\b", c, maxsplit=1, flags=re.IGNORECASE)
    if len(parts) == 2:
        left, rest = parts
        res = re.split(r"\b(?:então|entao|deve|o sistema)\b", rest, maxsplit=1, flags=re.IGNORECASE)
        when = _clean(res[0])
        then = _clean(res[1]) if len(res) == 2 else c
        given = _clean(left) or f"que o {story.persona} está autenticado no sistema"
        return given, when, then
    return (
        f"que o {story.persona} está na tela da funcionalidade",
        f"ele tenta {story.action}",
        c[0].lower() + c[1:] if c else c,
    )


# --------------------------------------------------------------------------- #
# Geradores
# --------------------------------------------------------------------------- #
def gen_bdd(story: Story) -> str:
    out = [
        "```gherkin",
        f"# language: pt",
        f"Funcionalidade: {story.title}",
        f"  Como {story.persona}",
        f"  Quero {story.action}",
        f"  Para {story.benefit}",
        "",
        "  Contexto:",
        f"    Dado que o {story.persona} possui acesso ao sistema",
        "",
    ]
    for i, c in enumerate(story.criteria, 1):
        g, w, t = criterion_to_given_when_then(c, story)
        tag = "@negativo" if is_negative(c) else "@positivo"
        out += [
            f"  {tag} @CT{i:03d}",
            f"  Cenário: {c[:80]}",
            f"    Dado {g}",
            f"    Quando {w}",
            f"    Então {t}",
            "",
        ]
    out += [
        "  @negativo @borda",
        "  Esquema do Cenário: Validação de dados de entrada",
        f"    Dado que o {story.persona} está na tela da funcionalidade",
        "    Quando informar o valor \"<entrada>\"",
        "    Então o sistema deve exibir \"<resultado>\"",
        "",
        "    Exemplos:",
        "      | entrada        | resultado                 |",
        "      | valor válido   | operação concluída        |",
        "      | campo vazio    | mensagem de obrigatório   |",
        "      | valor inválido | mensagem de erro amigável |",
        "```",
    ]
    return "\n".join(out)


def gen_steps(story: Story) -> str:
    out = [f"## 🧪 Casos de Teste — {story.title}", ""]
    for i, c in enumerate(story.criteria, 1):
        g, w, t = criterion_to_given_when_then(c, story)
        kind = "Negativo" if is_negative(c) else "Positivo"
        out += [
            f"### CT{i:03d} — {c[:90]}",
            f"**Tipo:** {kind} &nbsp;|&nbsp; **Prioridade:** {'Alta' if i <= 2 else 'Média'}",
            "",
            f"**Pré-condição:** {g[0].upper() + g[1:]}.",
            "",
            "| # | Ação | Resultado Esperado |",
            "|---|------|--------------------|",
            "| 1 | Acessar o sistema com credenciais válidas | Tela inicial exibida |",
            f"| 2 | Navegar até a funcionalidade \"{story.title}\" | Tela carregada sem erros |",
            f"| 3 | {w[0].upper() + w[1:]} | Sistema processa a ação |",
            f"| 4 | Validar o comportamento | {t[0].upper() + t[1:]} |",
            "",
        ]
    return "\n".join(out)


def gen_summary(story: Story) -> str:
    out = [f"## 📝 Resumo de Testes — {story.title}", ""]
    out.append(
        f"Esta validação garante que o **{story.persona}** consiga **{story.action}**, "
        f"com o objetivo de **{story.benefit}**. Os testes abrangem fluxos positivos, "
        "negativos e de borda, verificando regras de negócio, mensagens ao usuário e "
        "integridade dos dados."
    )
    out.append("")
    for i, c in enumerate(story.criteria, 1):
        _, w, t = criterion_to_given_when_then(c, story)
        out.append(
            f"**CT{i:03d}.** Ao executar a ação em que {w}, o sistema deve se comportar "
            f"conforme a regra definida. **Resultado esperado:** {t}."
        )
        out.append("")
    out.append(
        "> ✅ **Resultado esperado geral:** todas as regras de aceitação são atendidas, "
        "sem erros inesperados, com feedback claro ao usuário e dados persistidos corretamente."
    )
    return "\n".join(out)


GENERATORS = {"bdd": gen_bdd, "steps": gen_steps, "summary": gen_summary}

