def generate_with_ai(text: str, fmt: str, api_key: str, model: str, base_url: str) -> str:
    from openai import OpenAI  # import tardio: dependência opcional

    client = OpenAI(api_key=api_key, base_url=base_url or None)
    resp = client.chat.completions.create(
        model=model,
        temperature=0.3,
        messages=[
            {"role": "system", "content": "Você é um Analista de QA Sênior. " + PROMPTS[fmt]},
            {"role": "user", "content": text},
        ],
    )
    return resp.choices[0].message.content or ""


# --------------------------------------------------------------------------- #
# Geração de PDF (fpdf2)
# --------------------------------------------------------------------------- #
def _pdf_safe(text: str) -> str:
    """Normalize Markdown and punctuation without printing emoji placeholders."""
    import html
    text = html.unescape(text)
    text = re.sub(r"\*\*(.+?)\*\*", r"\1", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    for source, replacement in {
        "—": " - ", "–": "-", "“": '"', "”": '"', "‘": "'", "’": "'",
        "…": "...", "\u00a0": " ", "→": " -> ", "≥": ">=", "≤": "<=",
    }.items():
        text = text.replace(source, replacement)
    return text.encode("latin-1", "ignore").decode("latin-1").strip()


def prepare_client_logo(uploaded_bytes: bytes) -> bytes:
    """Validate and normalize an uploaded bitmap without companion files."""
    from PIL import Image, ImageOps, UnidentifiedImageError
    import warnings
    if len(uploaded_bytes) > 10 * 1024 * 1024:
        raise ValueError("A logo deve ter no máximo 10 MB.")
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", Image.DecompressionBombWarning)
            with Image.open(io.BytesIO(uploaded_bytes)) as image:
                if image.format not in ("PNG", "JPEG"):
                    raise ValueError("Envie uma imagem PNG ou JPG válida.")
                image = ImageOps.exif_transpose(image)
                image.thumbnail((1600, 1600))
                image = image.convert("RGBA")
                output = io.BytesIO()
                image.save(output, format="PNG")
                return output.getvalue()
    except (UnidentifiedImageError, OSError, Image.DecompressionBombError,
            Image.DecompressionBombWarning) as exc:
        raise ValueError("Não foi possível ler a logo. Envie outra imagem PNG ou JPG.") from exc


def make_pdf(markdown_text: str, title: str = "Cenários de Teste", *,
             qa_name: str = "", project_name: str = "", sprint: str = "", pdf_date: str = "",
             client_logo: bytes | None = None, evidence_images: dict | None = None,
             sprint_summary: dict | None = None, company_logo: bytes | None = None,
             card_code: str = "", card_link: str = "", title_link: str = "") -> bytes:
    """Render edited scenarios as a readable A4 report, with real wrapping tables."""
    from fpdf import FPDF
    from fpdf.enums import MethodReturnValue
    from fpdf.fonts import FontFace

    # Report palette: neutral ink and paper, with one restrained blue accent.
    ink = (31, 41, 55)
    muted = (100, 116, 139)
    accent = (37, 99, 160)
    rule = (218, 225, 232)
    pale = (243, 246, 249)

    # Only the explicitly uploaded client image enters the report.
    logo_bytes = prepare_client_logo(client_logo) if client_logo else None
    company_bytes = prepare_client_logo(company_logo) if company_logo else None
    left_rows = [("Nome do QA", qa_name), ("Nome do projeto", project_name), ("Data", pdf_date)]
    right_rows = [("Sprint", sprint), ("Código do card", card_code.strip()), ("Link Jira/Azure", card_link.strip())]
    safe_card_link = card_link.strip() if re.match(r"^https?://[^\s]+$", card_link.strip(), re.I) else ""
    safe_title_link = title_link.strip() if re.match(r"^https?://\S+$", title_link.strip(), re.I) else ""

    class ScenarioPDF(FPDF):
        def header(self):
            self.set_y(14)
            self.set_font("helvetica", "B", 9)
            self.set_text_color(*muted)
            self.cell(0, 6, "DOCUMENTAÇÃO DE TESTES", new_x="LMARGIN", new_y="NEXT")
            top = self.get_y() + 3
            logo_width = 26
            pair_width = (self.epw - logo_width) / 2
            label_width = 27
            value_width = pair_width - label_width
            row_heights = []
            for (_, left_value), (_, right_value) in zip(left_rows, right_rows):
                self.set_font("helvetica", "", 8.5)
                h_left = self.multi_cell(value_width - 5, 4.2, _pdf_safe(left_value) or "-",
                                         dry_run=True, output=MethodReturnValue.HEIGHT)
                h_right = self.multi_cell(value_width - 5, 4.2, _pdf_safe(right_value) or "-",
                                          dry_run=True, output=MethodReturnValue.HEIGHT)
                row_heights.append(max(9, h_left + 5, h_right + 5))
            total_height = sum(row_heights)
            self.set_draw_color(*rule)
            self.set_line_width(0.2)
            self.rect(self.l_margin, top, logo_width, total_height)
            if logo_bytes:
                self.image(io.BytesIO(logo_bytes), x=self.l_margin + 4, y=top + 4,
                           w=logo_width - 8, h=total_height - 8, keep_aspect_ratio=True)
            else:
                self.set_xy(self.l_margin + 2, top + total_height / 2 - 3)
                self.set_font("helvetica", "", 7)
                self.set_text_color(*muted)
                self.multi_cell(logo_width - 4, 4, "Logo do cliente", align="C")
            y = top
            for row, height in enumerate(row_heights):
                for side, (label, value) in enumerate((left_rows[row], right_rows[row])):
                    x = self.l_margin + logo_width + side * pair_width
                    self.set_fill_color(*pale)
                    self.rect(x, y, label_width, height, style="DF")
                    self.rect(x + label_width, y, value_width, height)
                    self.set_xy(x + 2.5, y + 3)
                    self.set_font("helvetica", "B", 7)
                    self.set_text_color(*muted)
                    self.cell(label_width - 5, 4, label)
                    self.set_xy(x + label_width + 2.5, y + 3)
                    link_row = label == "Link Jira/Azure"
                    self.set_font("helvetica", "", 7 if link_row else 8.5)
                    self.set_text_color(*ink)
                    self.multi_cell(value_width - 5, 4.2, _pdf_safe(value) or "-",
                                    link=safe_card_link if link_row else "",
                                    new_x="LMARGIN", new_y="NEXT")
                y += height
            self.set_xy(self.l_margin, top + total_height + 9)

        def footer(self):
            self.set_y(-21)
            self.set_draw_color(*rule)
            self.set_line_width(0.2)
            self.line(self.l_margin, self.get_y(), self.w - self.r_margin, self.get_y())
            text_x = self.l_margin
            if company_bytes:
                self.image(io.BytesIO(company_bytes), x=self.l_margin, y=self.h - 18.5,
                           w=38, h=11, keep_aspect_ratio=True)
                text_x = self.l_margin + 42
            self.set_xy(text_x, -15)
            self.set_font("helvetica", "", 8)
            self.set_text_color(*muted)
            self.cell(self.w - self.r_margin - text_x - 40, 5, "Documentação de testes")
            self.cell(40, 5, f"Página {self.page_no()} de {{nb}}", align="R")

    pdf = ScenarioPDF(format="A4")
    pdf.set_margins(18, 28, 18)
    pdf.set_auto_page_break(auto=True, margin=27)
    pdf.alias_nb_pages()
    pdf.set_title(_pdf_safe(title))
    pdf.set_author(_pdf_safe(qa_name))
    pdf.add_page()

    def write(text, size=10, bold=False, color=ink, gap=2, keep_next=0, link=""):
        safe = _pdf_safe(text)
        if not safe:
            return
        pdf.set_font("helvetica", "B" if bold else "", size)
        height = pdf.multi_cell(pdf.epw, size * 0.49, safe, dry_run=True,
                                output=MethodReturnValue.HEIGHT)
        if pdf.will_page_break(height + keep_next):
            pdf.add_page()
        pdf.set_font("helvetica", "B" if bold else "", size)
        pdf.set_text_color(*color)
        pdf.multi_cell(pdf.epw, size * 0.49, safe, align="L", new_x="LMARGIN", new_y="NEXT", link=link)
        pdf.ln(gap)

    write(title, size=23, bold=True, gap=7, keep_next=18, link=safe_title_link)
    if sprint_summary and sprint_summary.get('total'):
        write('Resumo da sprint', size=14, bold=True, gap=5, keep_next=95)
        counts = sprint_summary.get('counts', {})
        cards = [('Total', sprint_summary['total'], ink), ('Aprovado', counts.get('Aprovado', 0), (22, 120, 70)),
                 ('Reprovado', counts.get('Reprovado', 0), (178, 45, 48)),
                 ('Bloqueado', counts.get('Bloqueado', 0), (176, 122, 4)),
                 ('Não executado', counts.get('Não executado', 0), muted)]
        card_width = (pdf.epw - 4 * 3) / 5
        card_height = 16
        x = pdf.l_margin
        top = pdf.get_y()
        for label, value, color in cards:
            pdf.set_fill_color(*pale)
            pdf.set_draw_color(*rule)
            pdf.set_line_width(0.2)
            pdf.rect(x, top, card_width, card_height, style='DF')
            pdf.set_xy(x, top + 1.5)
            pdf.set_font('helvetica', '', 7.5)
            pdf.set_text_color(*muted)
            pdf.cell(card_width, 4.5, _pdf_safe(label), align='C')
            pdf.set_xy(x, top + 6)
            pdf.set_font('helvetica', 'B', 12)
            pdf.set_text_color(*color)
            pdf.cell(card_width, 6, str(value), align='C')
            x += card_width + 3
        pdf.set_y(top + card_height + 6)
        write(f"{sprint_summary.get('pass_rate', 0)}% de aprovação entre os "
              f"{sprint_summary.get('executed', 0)} cenários executados de {sprint_summary['total']}.",
              size=9, color=muted, gap=4)
        bar_max = pdf.epw - 56
        for label, value, color in cards[1:]:
            y = pdf.get_y()
            pdf.set_xy(pdf.l_margin, y)
            pdf.set_font('helvetica', '', 8.5)
            pdf.set_text_color(*muted)
            pdf.cell(26, 5.5, _pdf_safe(label))
            pdf.set_fill_color(*pale)
            pdf.rect(pdf.l_margin + 26, y + 0.5, bar_max, 4.5, style='F')
            if value:
                pdf.set_fill_color(*color)
                pdf.rect(pdf.l_margin + 26, y + 0.5, bar_max * value / sprint_summary['total'], 4.5, style='F')
            pdf.set_xy(pdf.l_margin + 26 + bar_max + 3, y)
            pdf.set_font('helvetica', '', 8.5)
            pdf.set_text_color(*ink)
            pdf.cell(20, 5.5, str(value))
            pdf.set_y(y + 7)
        pdf.ln(4)
    lines = markdown_text.splitlines()
    if lines and lines[0].strip() == '## ' + title:
        lines = lines[1:]
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            pdf.ln(2)
            i += 1
            continue
        evidence_match = re.fullmatch(r"\[\[QA_EVIDENCE:([a-f0-9]+)\]\]", line)
        if evidence_match:
            image_data = (evidence_images or {}).get(evidence_match.group(1))
            if image_data:
                image_data = prepare_client_logo(image_data)
                from PIL import Image
                with Image.open(io.BytesIO(image_data)) as image:
                    width, height = image.size
                display_width = min(pdf.epw, 150)
                display_height = display_width * height / width
                if display_height > 95:
                    display_width *= 95 / display_height
                    display_height = 95
                if pdf.will_page_break(display_height + 5):
                    pdf.add_page()
                pdf.image(io.BytesIO(image_data), x=pdf.l_margin, y=pdf.get_y(), w=display_width, h=display_height)
                pdf.set_y(pdf.get_y() + display_height + 5)
            i += 1
            continue
        if line.startswith("```") or line.startswith("# language:"):
            i += 1
            continue
        if line.startswith("|"):
            rows = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                cells = re.split(r"(?<!\\)\|", lines[i].strip().strip("|"))
                cells = [_pdf_safe(cell.replace(r"\|", "|").replace("<br>", " ")) for cell in cells]
                if not all(re.fullmatch(r":?-{2,}:?", c.replace(" ", "")) for c in cells):
                    rows.append(cells)
                i += 1
            if rows:
                columns = max(len(row) for row in rows)
                widths = (0.09, 0.45, 0.46) if columns == 3 else tuple(1 / columns for _ in range(columns))
                pdf.set_font("helvetica", "", 9)
                pdf.set_text_color(*ink)
                pdf.set_draw_color(*rule)
                pdf.set_line_width(0.15)
                with pdf.table(
                    col_widths=widths, width=pdf.epw, line_height=4.7,
                    padding=2.3, borders_layout="HORIZONTAL_LINES",
                    headings_style=FontFace(emphasis="BOLD", color=ink, fill_color=pale),
                    cell_fill_color=pale, cell_fill_mode="ROWS",
                    repeat_headings=1, text_align="LEFT",
                ) as table:
                    for cells in rows:
                        row = table.row()
                        for cell in cells + [""] * (columns - len(cells)):
                            row.cell(cell)
                pdf.ln(4)
            continue
        heading = re.match(r"^(#{1,6})\s+(.+)$", line)
        if heading:
            level = len(heading.group(1))
            pdf.ln(3)
            reserve = 18
            if re.match(r"CT\d+", _pdf_safe(heading.group(2))):
                reserve = 65
                for upcoming in lines[i + 1:]:
                    if upcoming.strip().startswith("### "):
                        break
                    if upcoming.strip().startswith("| 1 |"):
                        cells = upcoming.strip().strip("|").split("|")
                        pdf.set_font("helvetica", "", 9)
                        heights = [pdf.multi_cell(pdf.epw * width - 4.6, 4.7,
                                   _pdf_safe(cell), dry_run=True,
                                   output=MethodReturnValue.HEIGHT)
                                   for cell, width in zip(cells, (0.09, 0.45, 0.46))]
                        reserve = min(155, 45 + max(heights, default=5))
                        break
            write(heading.group(2), size=14 if level <= 2 else 11.5,
                  bold=True, color=ink if level <= 2 else accent, gap=3, keep_next=reserve)
        elif line.startswith(("Funcionalidade:", "Cenário:", "Esquema do Cenário:")):
            pdf.ln(3)
            write(line, size=13 if line.startswith("Funcionalidade:") else 11.5,
                  bold=True, color=accent, gap=3, keep_next=18)
        elif line.startswith("@"):
            # Keep scenario tags with their title and the first step.
            write(line, size=8, color=muted, gap=1, keep_next=32)
        elif line.startswith(("Contexto:", "Exemplos:")):
            write(line, size=10, bold=True, gap=2, keep_next=45 if line.startswith("Exemplos:") else 14)
        elif re.match(r"^\*\*CT\d+", line):
            match = re.match(r"^\*\*(CT\d+[.:]?)\*\*\s*(.*)", line)
            if match:
                pdf.ln(3)
                write(match.group(1).rstrip(".:"), size=11.5, bold=True,
                      color=accent, gap=2, keep_next=15)
                write(match.group(2), gap=4)
            else:
                write(line)
        elif line.startswith(">"):
            pdf.ln(3)
            write(line.lstrip("> "), bold=True, gap=4)
        elif line.startswith(("**Tipo:", "**Prioridade:")):
            write(line, size=9, color=muted, gap=3)
        else:
            write(line, gap=2)
        i += 1
    return bytes(pdf.output())


