def copy_button(text: str, key: str) -> None:
    payload = json.dumps(text).replace("<", "\\u003c")
    components.html(
        f"""
        <button id="btn-{key}" style="background:#fff;color:#161616;border:1px solid #dfe2e6;border-radius:6px;
          padding:12px 14px;font-weight:600;cursor:pointer;font-family:sans-serif;">
          Copiar cenários</button>
        <span id="ok-{key}" style="margin-left:10px;font-family:sans-serif;color:#626262;"></span>
        <script>
          document.getElementById("btn-{key}").onclick = async () => {{
            const t = {payload};
            try {{ await navigator.clipboard.writeText(t); }}
            catch(e) {{ const a=document.createElement('textarea'); a.value=t;
              document.body.appendChild(a); a.select(); document.execCommand('copy'); a.remove(); }}
            document.getElementById("ok-{key}").innerText = "Copiado!";
            setTimeout(()=>document.getElementById("ok-{key}").innerText="", 2000);
          }};
        </script>
        """,
        height=55,
    )


# --------------------------------------------------------------------------- #
# Structured scenarios, coverage, execution, CSV and local snapshot history
# --------------------------------------------------------------------------- #
import csv
import sqlite3
import uuid
from pathlib import Path
from datetime import datetime, timezone

STATUSES = ('Não executado', 'Aprovado', 'Reprovado', 'Bloqueado')
KINDS = ('Positivo', 'Negativo', 'Limite')
DRAFT_PLACEHOLDER = 'A definir pelo QA'


def new_scenario(title='', *, criterion_ids=None, precondition='', steps='', expected='', kind='Positivo'):
    return dict(id=uuid.uuid4().hex, title=title, criterion_ids=list(criterion_ids or []),
                precondition=precondition, steps=steps, expected=expected, kind=kind,
                priority='Média', status='Não executado', observations='', evidence=[], bug={}, retests=[])


def build_scenarios(story):
    scenarios = []
    for i, criterion in enumerate(story.criteria):
        given, when, then = criterion_to_given_when_then(criterion, story)
        scenario = new_scenario(criterion[:120], criterion_ids=[i], precondition=given,
                                steps=when, expected=then,
                                kind='Negativo' if is_negative(criterion) else 'Positivo')
        scenario['priority'] = 'Alta' if i < 2 else 'Média'
        scenarios.append(scenario)
    return scenarios


def coverage_rows(criteria, scenarios):
    """Explicit links show traceability, not proof of semantic coverage."""
    return [{'criterion': criterion, 'linked': sum(i in s.get('criterion_ids', []) for s in scenarios)}
            for i, criterion in enumerate(criteria)]


def review_suggestions(criteria, scenarios):
    suggestions = []
    for i, criterion in enumerate(criteria):
        linked = [s for s in scenarios if i in s.get('criterion_ids', [])]
        if not linked:
            suggestions.append(dict(criterion_id=i, kind='Positivo', title='Critério sem cenário', criterion=criterion))
        for kind in ('Negativo', 'Limite'):
            if not any(s['kind'] == kind for s in linked):
                suggestions.append(dict(criterion_id=i, kind=kind,
                                        title=f'Revisar caso {kind.lower()}', criterion=criterion))
    return suggestions


def extract_requirement_text(filename: str, data: bytes) -> str:
    """Extrai texto de PDF ou Word para alimentar o campo de requisitos.

    Importações opcionais dentro da função: o app roda sem pypdf/python-docx
    até que o usuário importe um arquivo desses formatos."""
    name = filename.lower()
    if name.endswith('.pdf'):
        try:
            from pypdf import PdfReader
        except ImportError:
            raise ValueError('Para importar PDF, instale: pip install pypdf')
        try:
            text = '\n'.join((page.extract_text() or '') for page in PdfReader(io.BytesIO(data)).pages)
        except Exception:
            raise ValueError('Não consegui ler este PDF. Verifique se o arquivo não está corrompido ou protegido por senha.')
    elif name.endswith('.docx'):
        try:
            import docx
        except ImportError:
            raise ValueError('Para importar Word, instale: pip install python-docx')
        try:
            text = '\n'.join(paragraph.text for paragraph in docx.Document(io.BytesIO(data)).paragraphs)
        except Exception:
            raise ValueError('Não consegui ler este arquivo Word. Verifique se é um .docx válido (o formato antigo .doc não é suportado).')
    else:
        raise ValueError('Formato não suportado. Envie um arquivo .pdf ou .docx.')
    text = '\n'.join(line.rstrip() for line in text.splitlines() if line.strip())
    if not text.strip():
        raise ValueError('Não encontrei texto legível neste arquivo. Se for um PDF digitalizado (imagem), cole o texto manualmente.')
    return text


def bug_report_markdown(s, *, qa_name='', project_name='', sprint='', criteria=None):
    """Texto de defeito pronto para abrir um bug, a partir de um cenário reprovado."""
    criteria = criteria or []
    linked = ', '.join(f'CA{i+1:02d}' for i in s.get('criterion_ids', []) if 0 <= i < len(criteria))
    steps = [line.strip() for line in s['steps'].splitlines() if line.strip()]
    lines = [
        f'## Defeito — {s["title"]}',
        '',
        f'**Projeto:** {project_name or "-"} | **Sprint:** {sprint or "-"} | **QA:** {qa_name or "-"}',
        f'**Cenário:** {s["kind"]} · Prioridade {s["priority"]}' + (f' · Critérios: {linked}' if linked else ''),
        '',
        '**Pré-condições:**',
        s['precondition'] or '-',
        '',
        '**Passos para reproduzir:**',
        *[f'{n}. {step}' for n, step in enumerate(steps, 1)],
        '',
        f'**Resultado esperado:** {s["expected"] or "-"}',
        f'**Resultado obtido:** {s["observations"] or "-"}',
    ]
    if s.get('evidence'):
        lines += ['', '**Evidências (anexar as imagens no bug):**']
        lines += [f'- {ev["name"]}' for ev in s['evidence']]
    return '\n'.join(lines)


SEVERITIES = ('Baixa', 'Média', 'Alta', 'Crítica')
BUG_TOOL_EXPORTS = ('Jira', 'Azure DevOps')


def defect_draft(s):
    """Campos iniciais do defeito a partir do cenário reprovado; tudo editável na aba Defeitos."""
    return dict(title=s['title'], severity='Alta', environment='',
                precondition=s['precondition'], steps=s['steps'],
                expected=s['expected'], actual=s['observations'])


def ensure_bug(s):
    if not s.get('bug'):
        s['bug'] = defect_draft(s)
    s['bug'].setdefault('id', uuid.uuid4().hex)
    s['bug'].setdefault('external_ref', '')
    s['bug'].setdefault('external_link', '')
    s['bug'].setdefault('evidence', [])
    s['bug'].setdefault('original_failure', json.loads(json.dumps(dict(
        status=s['status'], observations=s['observations'], evidence=s.get('evidence', []),
        precondition=s['precondition'], steps=s['steps'], expected=s['expected']))))
    s.setdefault('retests', [])
    return s['bug']


RETEST_STATUSES = ('Aprovado', 'Reprovado', 'Bloqueado')


def effective_status(s):
    attempts = s.get('retests', [])
    override = s.get('execution_override', {})
    if attempts and attempts[-1]['status'] == 'Aprovado' and override.get('retest_id') == attempts[-1]['id'] and override.get('status') in STATUSES:
        return override['status']
    return attempts[-1]['status'] if attempts else s['status']


def execution_status_editable(s):
    attempts = s.get('retests', [])
    return not s.get('bug') or bool(attempts and attempts[-1]['status'] == 'Aprovado')


def set_execution_status(s, status):
    if status not in STATUSES or not execution_status_editable(s):
        raise ValueError('Registre um reteste aprovado para liberar o status deste cenário.')
    attempts = s.get('retests', [])
    if attempts:
        s['execution_override'] = dict(status=status, retest_id=attempts[-1]['id'])
    else:
        s['status'] = status


def persist_execution(store, payload, changes, snapshot_id=None):
    """Validate a detached batch and save it before changing live records."""
    frozen = json.loads(json.dumps(payload))
    for row in frozen['scenarios']:
        change = changes.get(row['id'])
        if change is None:
            continue
        if execution_status_editable(row):
            set_execution_status(row, change['status'])
        elif change['status'] != effective_status(row):
            raise ValueError('Registre um reteste aprovado para liberar o status deste cenário.')
        if not row.get('retests'):
            row['observations'] = change.get('observations', row['observations'])
            removed = set(change.get('remove_evidence', []))
            row['evidence'] = [ev for ev in row.get('evidence', []) if ev['id'] not in removed]
            for ev in change.get('evidence', []):
                image = prepare_client_logo(base64.b64decode(ev['data'], validate=True))
                row['evidence'].append(dict(id=uuid.uuid4().hex, name=Path(ev['name']).name,
                                           data=base64.b64encode(image).decode()))
        if row['status'] == 'Reprovado':
            ensure_bug(row)
    identifier = save_snapshot(store, frozen, snapshot_id)
    return frozen, identifier


def execution_defect_evidence(s):
    """Keep execution provenance, including frozen original-failure attachments."""
    images = list(s.get('evidence', []))
    images += s.get('bug', {}).get('original_failure', {}).get('evidence', [])
    return list({image['id']: image for image in images}.values())


def persist_defect_evidence(store, payload, scenario_id, images, snapshot_id=None, remove_ids=None):
    """Validate and save detached defect attachments without rewriting execution or retests."""
    frozen = json.loads(json.dumps(payload))
    target = next((row for row in frozen['scenarios'] if row['id'] == scenario_id), None)
    if target is None or not (target.get('bug') or target['status'] == 'Reprovado'):
        raise ValueError('Defeito não encontrado para este cenário.')
    bug = ensure_bug(target)
    removed = set(remove_ids or [])
    attachments = [image for image in bug['evidence'] if image['id'] not in removed]
    for image in images:
        data = prepare_client_logo(base64.b64decode(image['data'], validate=True))
        attachments.append(dict(id=uuid.uuid4().hex, name=Path(image['name']).name,
                                data=base64.b64encode(data).decode()))
    bug['evidence'] = attachments
    identifier = save_snapshot(store, frozen, snapshot_id)
    return frozen, identifier


def defect_status(s):
    attempts = s.get('retests', [])
    if not attempts:
        return 'Aberto'
    return {'Aprovado': 'Resolvido', 'Reprovado': 'Reaberto', 'Bloqueado': 'Reteste bloqueado'}[attempts[-1]['status']]


def record_retest(s, status, *, actual, qa_name, environment='', version='', evidence=None,
                  project_name='', sprint=''):
    if status not in RETEST_STATUSES:
        raise ValueError('Selecione um resultado de reteste válido.')
    if not s.get('bug') and s['status'] != 'Reprovado':
        raise ValueError('O cenário precisa ter um defeito aberto antes do reteste.')
    if not actual.strip() or not qa_name.strip():
        raise ValueError('Preencha o QA responsável e o resultado obtido.')
    validated = []
    for image in evidence or []:
        data = prepare_client_logo(base64.b64decode(image['data'], validate=True))
        validated.append(dict(id=uuid.uuid4().hex, name=Path(image['name']).name,
                              data=base64.b64encode(data).decode()))
    bug = ensure_bug(s)
    if not s['retests']:
        bug['original_failure'] = json.loads(json.dumps(dict(
            status=s['status'], observations=s['observations'], evidence=s.get('evidence', []),
            precondition=s['precondition'], steps=s['steps'], expected=s['expected'])))
    attempt = dict(id=uuid.uuid4().hex, scenario_id=s['id'], bug_id=bug['id'],
                   number=len(s['retests']) + 1, saved_at=datetime.now(timezone.utc).isoformat(),
                   status=status, actual=actual.strip(), qa_name=qa_name.strip(),
                   environment=environment, version=version, evidence=validated,
                   project_name=project_name, sprint=sprint,
                   scenario_title=s['title'], bug_title=bug['title'], external_ref=bug['external_ref'],
                   external_link=bug.get('external_link', ''),
                   precondition=bug['precondition'], steps=bug['steps'], expected=bug['expected'])
    s['retests'].append(attempt)
    s.pop('execution_override', None)
    return attempt


def persist_retest(store, payload, scenario_id, status, *, snapshot_id=None, **fields):
    # Work on a detached copy; neither an invalid image nor a failed write can
    # leave a partial attempt in the live scenario records.
    frozen = json.loads(json.dumps(payload))
    target = next((row for row in frozen['scenarios'] if row['id'] == scenario_id), None)
    if target is None:
        raise ValueError('Cenário não encontrado.')
    attempt = record_retest(target, status, **fields)
    snapshot_id = save_snapshot(store, frozen, snapshot_id)
    return frozen, attempt, snapshot_id


def retest_markdown(scenarios, *, evidence_refs=False):
    lines = []
    for s in scenarios:
        for attempt in s.get('retests', []):
            card = attempt['external_ref'] or attempt.get('external_link') or '-'
            if attempt.get('external_ref') and attempt.get('external_link'):
                card = f'{attempt["external_ref"]} ({attempt["external_link"]})'
            lines += [f'### Reteste {attempt["number"]} — {attempt["scenario_title"]}',
                      f'**Defeito:** {attempt["bug_title"]} | **Card do bug:** {card}',
                      f'**Data (UTC):** {attempt["saved_at"]}',
                      f'**Projeto:** {attempt["project_name"]} | **Sprint:** {attempt["sprint"]}',
                      f'**QA:** {attempt["qa_name"]} | **Ambiente:** {attempt["environment"] or "-"} | **Versão:** {attempt["version"] or "-"}',
                      f'**Status:** {attempt["status"]}',
                      f'**Pré-condições:** {attempt["precondition"]}',
                      '**Passos:**', steps_to_numbered(attempt['steps']),
                      f'**Resultado esperado:** {attempt["expected"]}',
                      f'**Resultado obtido:** {attempt["actual"]}']
            for ev in attempt['evidence']:
                lines.append(f'**Evidência:** {ev["name"]}')
                if evidence_refs:
                    lines.append(f'[[QA_EVIDENCE:{ev["id"]}]]')
            lines.append('')
    return '\n\n'.join(lines)


def display_evidence(images, *, caption_prefix='', width=280):
    for ev in images:
        try:
            data = prepare_client_logo(base64.b64decode(ev.get('data', ''), validate=True))
            st.image(data, caption=caption_prefix + ev.get('name', 'Evidência'), width=width)
        except (ValueError, TypeError):
            st.warning(f'Não foi possível abrir a imagem {ev.get("name", "Evidência")}. Anexe novamente o arquivo original.')


def display_retest_history(s):
    for attempt in s.get('retests', []):
        with st.expander(f'Tentativa {attempt["number"]} · {attempt["status"]} · {attempt["qa_name"]}', expanded=True):
            st.markdown(retest_markdown([dict(retests=[attempt])]))
            if attempt.get('evidence'):
                display_evidence(attempt['evidence'], caption_prefix=f'Reteste {attempt["number"]} · ')
            else:
                st.caption('Nenhuma imagem anexada nesta tentativa.')


def report_images(scenarios):
    return {ev['id']: base64.b64decode(ev['data']) for s in scenarios
            for ev in (execution_defect_evidence(s) + s.get('bug', {}).get('evidence', [])
                       + [e for a in s.get('retests', []) for e in a['evidence']])}


def retest_csv(scenarios):
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, quoting=csv.QUOTE_ALL)
    codes = {row['id']: f'CT{index+1:03d}' for index, row in enumerate(scenarios)}
    writer.writerow(['Cenário', 'Defeito', 'Bug Jira/Azure', 'Tentativa', 'Data (UTC)', 'Status',
                     'QA', 'Projeto', 'Sprint', 'Ambiente', 'Versão',
                     'Resultado esperado', 'Resultado obtido', 'Evidências'])
    for s in scenarios:
        for a in s.get('retests', []):
            values = [codes[s['id']], a['scenario_title'], a['bug_title'],
                      f'{a["number"]}º', a['saved_at'], a['status'], a['qa_name'],
                      a['project_name'], a['sprint'], a['environment'], a['version'],
                      a['expected'], a['actual']]
            writer.writerow([csv_value(v) for v in values] + [csv_value('; '.join(e['name'] for e in a['evidence']))])
    return ('\ufeff' + buffer.getvalue()).encode('utf-8')


def retest_summary_rows(scenarios):
    """Uma linha por item retestado: quantas tentativas e todos os resultados obtidos."""
    rows = []
    codes = {row['id']: f'CT{index+1:03d}' for index, row in enumerate(scenarios)}
    for s in scenarios:
        attempts = s.get('retests', [])
        if not attempts:
            continue
        rows.append({
            'Cenário': f'{codes[s["id"]]} · {s["title"]}',
            'Defeito': attempts[0]['bug_title'],
            'Card do bug': attempts[0]['external_ref'] or attempts[0].get('external_link') or '-',
            'Vezes retestado': len(attempts),
            'Resultados (em ordem)': ' → '.join(f'{a["number"]}º {a["status"]}' for a in attempts),
            'Situação atual': defect_status(s),
            'Último reteste (UTC)': attempts[-1]['saved_at'][:19].replace('T', ' '),
            'Último QA': attempts[-1]['qa_name'],
        })
    return rows


def retest_attempt_rows(scenarios):
    """Uma linha por tentativa de reteste, na ordem em que foram registradas."""
    rows = []
    codes = {row['id']: f'CT{index+1:03d}' for index, row in enumerate(scenarios)}
    for s in scenarios:
        for a in s.get('retests', []):
            rows.append({
                'Cenário': f'{codes[s["id"]]} · {s["title"]}',
                'Tentativa': f'{a["number"]}º',
                'Resultado': a['status'],
                'Data (UTC)': a['saved_at'][:19].replace('T', ' '),
                'QA': a['qa_name'],
                'Ambiente': a['environment'] or '-',
                'Versão': a['version'] or '-',
                'Resultado obtido': a['actual'],
                'Evidências': '; '.join(e['name'] for e in a['evidence']) or '-',
            })
    return rows


def defect_markdown(s, *, qa_name='', project_name='', sprint='', criteria=None, evidence_refs=False, scenario_code=''):
    """Relatório de defeito montado a partir dos campos editáveis, não do cenário bruto."""
    criteria = criteria or []
    bug = ensure_bug(s)
    linked = ', '.join(f'CA{i+1:02d}' for i in s.get('criterion_ids', []) if 0 <= i < len(criteria))
    steps = [line.strip() for line in bug['steps'].splitlines() if line.strip()]
    bug_code = bug['external_ref'].strip()
    bug_link = bug.get('external_link', '').strip()
    card_text = f'[{bug_code}]({bug_link})' if bug_code and bug_link else (bug_code or bug_link or '-')
    lines = [
        f'## Defeito — {bug["title"]}',
        '',
        f'**Projeto:** {project_name or "-"} | **Sprint:** {sprint or "-"} | **QA:** {qa_name or "-"}',
        f'**Severidade:** {bug["severity"]} | **Ambiente:** {bug["environment"] or "-"}',
        f'**Situação do defeito:** {defect_status(s)} | **Card do bug:** {card_text}',
        f'**Cenário de origem:** ' + (f'{scenario_code} · ' if scenario_code else '') + f'{s["kind"]} · Prioridade {s["priority"]}' + (f' · Critérios: {linked}' if linked else ''),
        '',
        '**Pré-condições:**',
        bug['precondition'] or '-',
        '',
        '**Passos para reproduzir:**',
        *[f'{n}. {step}' for n, step in enumerate(steps, 1)],
        '',
        f'**Resultado esperado:** {bug["expected"] or "-"}',
        f'**Resultado obtido:** {bug["actual"] or "-"}',
    ]
    for label, images in [('Evidências da execução', execution_defect_evidence(s)),
                          ('Evidências extras do defeito', bug.get('evidence', []))]:
        if images:
            lines += ['', f'**{label}:**']
            for ev in images:
                lines.append(f'- {ev["name"]}')
                if evidence_refs:
                    lines.append(f'[[QA_EVIDENCE:{ev["id"]}]]')
    if s.get('retests'):
        lines += ['', '## Histórico de retestes', retest_markdown([s], evidence_refs=evidence_refs)]
    return '\n'.join(lines)


def defect_tool_export(failed, tool, *, project_name='', sprint=''):
    """CSV de defeitos no layout de importação do Jira ou do Azure DevOps."""
    if tool not in BUG_TOOL_EXPORTS:
        raise ValueError('Ferramenta de exportação de defeitos não suportada.')
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, delimiter=',', quoting=csv.QUOTE_ALL)

    def description(bug, scenario):
        steps = [line.strip() for line in bug['steps'].splitlines() if line.strip()]
        parts = [f'Pre-condicoes: {bug["precondition"] or "-"}', '', 'Passos para reproduzir:']
        parts += [f'{n}. {step}' for n, step in enumerate(steps, 1)]
        parts += ['', f'Resultado esperado: {bug["expected"] or "-"}',
                  f'Resultado obtido: {bug["actual"] or "-"}',
                  f'Sprint: {sprint or "-"}']
        images = execution_defect_evidence(scenario) + bug.get('evidence', [])
        parts += ['', 'Evidências: ' + '; '.join(image['name'] for image in images)]
        return '\n'.join(parts)

    if tool == 'Jira':
        writer.writerow(['Summary', 'Issue Type', 'Priority', 'Severity', 'Environment', 'Description', 'Labels'])
        for s in failed:
            bug = ensure_bug(s)
            writer.writerow([csv_value(v) for v in
                             [bug['title'], 'Bug', s['priority'], bug['severity'],
                              bug['environment'], description(bug, s) + '\n' + retest_markdown([s]), project_name]])
    else:  # Azure DevOps
        writer.writerow(['Work Item Type', 'Title', 'Priority', 'Severity', 'Repro Steps', 'System Info', 'Tags'])
        for s in failed:
            bug = ensure_bug(s)
            writer.writerow([csv_value(v) for v in
                             ['Bug', bug['title'], s['priority'], bug['severity'],
                              description(bug, s) + '\n' + retest_markdown([s]), bug['environment'], project_name]])
    return ('﻿' + buffer.getvalue()).encode('utf-8')


def scenario_markdown(scenarios, fmt, title='Cenários de Teste', execution=False):
    out = [f'## {title}', '']
    for index, s in enumerate(scenarios, 1):
        out += [f'### CT{index:03d} — {s["title"]}',
                f'**Tipo:** {s["kind"]} | **Prioridade:** {s["priority"]}',
                f'**Pré-condição:** {s["precondition"]}', '']
        steps = [line.strip() for line in s['steps'].splitlines() if line.strip()]
        if fmt == 'bdd':
            out += ['```gherkin', f'Cenário: {s["title"]}', f'  Dado {s["precondition"]}']
            for n, step in enumerate(steps):
                out.append(f'  {"Quando" if n == 0 else "E"} {step}')
            out += [f'  Então {s["expected"]}', '```']
        elif fmt == 'steps':
            out += [f'{n}. {step}' for n, step in enumerate(steps, 1)]
            out += [f'**Resultado esperado:** {s["expected"]}']
        else:
            out += [f'{"; ".join(steps)}. **Resultado esperado:** {s["expected"]}']
        if execution:
            out += ['', f'**Status atual:** {effective_status(s)}', f'**Execução original:** {s["status"]}', f'**Observações:** {s["observations"] or "-"}']
            for ev in s.get('evidence', []):
                out += [f'**Evidência:** {ev["name"]}', f'[[QA_EVIDENCE:{ev["id"]}]]']
        if execution and s.get('retests'):
            out += ['', retest_markdown([s], evidence_refs=True)]
        out.append('')
    return '\n'.join(out)


GHERKIN_KEYS = {'dado': 'given', 'quando': 'when', 'então': 'then', 'entao': 'then'}


def scenario_to_gherkin(s):
    lines, pre = [], [l.strip() for l in s['precondition'].splitlines() if l.strip()]
    steps = [l.strip() for l in s['steps'].splitlines() if l.strip()]
    exp = [l.strip() for l in s['expected'].splitlines() if l.strip()]
    for word, items in (('Dado', pre), ('Quando', steps), ('Então', exp)):
        lines += [f'{word if n == 0 else "E"} {item}' for n, item in enumerate(items)]
    return '\n'.join(lines)


def gherkin_to_fields(text):
    parts, section = {'given': [], 'when': [], 'then': []}, 'given'
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.lower().startswith(('cenário:', 'cenario:')):
            continue
        word, _, rest = line.partition(' ')
        key = word.lower().rstrip(':')
        if key in GHERKIN_KEYS:
            section, line = GHERKIN_KEYS[key], rest.strip()
        elif key in ('e', 'mas'):
            line = rest.strip()
        parts[section].append(line)
    return {'precondition': '\n'.join(parts['given']), 'steps': '\n'.join(parts['when']),
            'expected': '\n'.join(parts['then'])}


def steps_to_numbered(steps):
    return '\n'.join(f'{n}. {l.strip()}' for n, l in enumerate([l for l in steps.splitlines() if l.strip()], 1))


def numbered_to_steps(text):
    return '\n'.join(re.sub(r'^\s*\d+\s*[.)\-]\s*', '', l).strip() for l in text.splitlines() if l.strip())


def steps_to_summary(steps):
    return '; '.join(l.strip() for l in steps.splitlines() if l.strip())


def summary_to_steps(text):
    return '\n'.join(p.strip().rstrip('.') for p in re.split(r';|\n', text) if p.strip())


def execution_counts(scenarios):
    return {status: sum(effective_status(s) == status for s in scenarios) for status in STATUSES}


def sprint_summary(scenarios):
    """Aggregated numbers for the sprint panel shown in the app and the PDF."""
    counts = execution_counts(scenarios)
    total = len(scenarios)
    executed = total - counts['Não executado']
    return dict(total=total, executed=executed, pending=counts['Não executado'], counts=counts,
                pass_rate=round(100 * counts['Aprovado'] / executed) if executed else 0)


TOOL_EXPORTS = ('Xray (Jira)', 'TestRail', 'Azure DevOps')


def tool_export(scenarios, tool, *, qa_name='', project_name='', sprint='', criteria=None):
    """CSV imports in the column layout expected by common test management tools."""
    if tool not in TOOL_EXPORTS:
        raise ValueError('Ferramenta de exportação não suportada.')
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, delimiter=',', quoting=csv.QUOTE_ALL)

    def rows_of(scenario):
        return [line.strip() for line in scenario['steps'].splitlines() if line.strip()]

    def references(scenario):
        return ', '.join(f'CA{i + 1:02d}' for i in scenario.get('criterion_ids', [])
                         if criteria is not None and 0 <= i < len(criteria))

    if tool == 'Xray (Jira)':
        writer.writerow(['Test Summary', 'Test Type', 'Steps', 'Step', 'Action', 'Data', 'Result'])
        for s in scenarios:
            steps = rows_of(s)
            for n, step in enumerate(steps, 1):
                writer.writerow([csv_value(value) for value in
                                 [s['title'], 'Manual', str(len(steps)), f'Step {n}', step, '',
                                  s['expected'] if n == len(steps) else '']])
    elif tool == 'TestRail':
        writer.writerow(['Title', 'Section', 'References', 'Priority', 'Preconditions', 'Steps', 'Expected Result'])
        for s in scenarios:
            steps = rows_of(s)
            writer.writerow([csv_value(value) for value in
                             [s['title'], project_name, references(s), s['priority'], s['precondition'],
                              '\n'.join(f'{n}. {step}' for n, step in enumerate(steps, 1)), s['expected']]])
    else:  # Azure DevOps
        writer.writerow(['Title', 'Step', 'Step Type', 'Action', 'Expected result'])
        for s in scenarios:
            steps = rows_of(s)
            for n, step in enumerate(steps, 1):
                writer.writerow([csv_value(value) for value in
                                 [s['title'], n, 'Action', step,
                                  s['expected'] if n == len(steps) else '']])
    return ('\ufeff' + buffer.getvalue()).encode('utf-8')


def csv_value(value):
    # Protect spreadsheet users against formulas from story/user-provided fields.
    text = str(value)
    return "'" + text if text.lstrip().startswith(('=', '+', '-', '@')) else text


def export_csv(scenarios, *, qa_name='', project_name='', sprint='', criteria=None):
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, delimiter=',', quoting=csv.QUOTE_ALL)
    writer.writerow(['Código', 'Título', 'Tipo', 'Prioridade', 'Pré-condições', 'Passos',
                     'Resultado esperado', 'Status', 'Observações', 'Evidências',
                     'QA', 'Projeto', 'Sprint', 'Critérios vinculados'])
    for index, s in enumerate(scenarios):
        links = [criteria[i] for i in s.get('criterion_ids', [])
                 if criteria is not None and 0 <= i < len(criteria)]
        writer.writerow([csv_value(value) for value in [f'CT{index+1:03d}', s['title'], s['kind'], s['priority'],
                         s['precondition'], s['steps'], s['expected'], effective_status(s), s['observations'],
                         '; '.join(e['name'] for e in s.get('evidence', [])),
                         qa_name, project_name, sprint, '\n'.join(links)]])
    return ('\ufeff' + buffer.getvalue()).encode('utf-8')


def history_path():
    configured = os.getenv('QAHUB_HISTORY_PATH')
    return Path(configured).expanduser() if configured else Path.home() / '.qahub' / 'history.sqlite3'


def history_connection(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path, timeout=10)
    connection.execute('CREATE TABLE IF NOT EXISTS snapshots (id TEXT PRIMARY KEY, saved_at TEXT NOT NULL, project TEXT NOT NULL, sprint TEXT NOT NULL, payload TEXT NOT NULL)')
    return connection


def save_snapshot(store, payload, identifier=None):
    payload = json.loads(json.dumps(payload))
    if isinstance(store, tuple):
        if store[0] != 'portable':
            raise ValueError('Formato de histórico desconhecido.')
        record = new_snapshot_record(payload)
        if identifier:
            record['id'] = identifier
        for index, existing in enumerate(store[1]):
            if existing['id'] == record['id']:
                store[1][index] = record
                break
        else:
            store[1].append(record)
        return record['id']
    identifier = identifier or uuid.uuid4().hex
    with history_connection(store) as connection:
        connection.execute('INSERT OR REPLACE INTO snapshots VALUES (?, ?, ?, ?, ?)',
                           (identifier, datetime.now(timezone.utc).isoformat(), payload.get('project_name', ''),
                            payload.get('sprint', ''), json.dumps(payload, ensure_ascii=False)))
    return identifier


def list_snapshots(store, project='', sprint=''):
    if isinstance(store, tuple):
        if store[0] != 'portable':
            raise ValueError('Formato de histórico desconhecido.')
        rows = [(record['id'], record['saved_at'], record.get('project', ''), record.get('sprint', ''))
                for record in store[1]]
    else:
        with history_connection(store) as connection:
            rows = connection.execute('SELECT id, saved_at, project, sprint FROM snapshots ORDER BY saved_at DESC').fetchall()
    return [dict(id=r[0], saved_at=r[1], project=r[2], sprint=r[3]) for r in rows
            if project.casefold() in r[2].casefold() and sprint.casefold() in r[3].casefold()]


def load_snapshot(store, identifier):
    if isinstance(store, tuple):
        record = next((item for item in store[1] if item['id'] == identifier), None)
        if record is None:
            raise ValueError('Registro não encontrado.')
        # Cópia desconectada: abrir a versão não altera os registros vivos.
        return json.loads(json.dumps(record['payload']))
    with history_connection(store) as connection:
        row = connection.execute('SELECT payload FROM snapshots WHERE id=?', (identifier,)).fetchone()
    if row is None:
        raise ValueError('Registro não encontrado.')
    return json.loads(row[0])


def delete_snapshot(store, identifier):
    if isinstance(store, tuple):
        store[1][:] = [item for item in store[1] if item['id'] != identifier]
        return
    with history_connection(store) as connection:
        connection.execute('DELETE FROM snapshots WHERE id=?', (identifier,))



# --------------------------- Histórico portátil --------------------------- #
# O arquivo .qahub é um ZIP com um JSON dentro. Ele carrega todas as versões
# salvas (cenários, defeitos, retestes e imagens em base64) para que cada QA
# leve o próprio histórico, inclusive no app publicado online.
HISTORY_FORMAT = 'qahub-history'


def history_writable(path):
    path = Path(path)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        probe = path.with_name(path.name + '.probe')
        probe.write_bytes(b'')
        probe.unlink()
        return True
    except OSError:
        return False


def history_store():
    mode = st.session_state.get('history_mode') or 'portable'
    if mode == 'portable':
        if 'portable_history' not in st.session_state:
            st.session_state['portable_history'] = []
        return ('portable', st.session_state['portable_history'])
    return history_path()


def new_snapshot_record(payload):
    return dict(id=uuid.uuid4().hex, saved_at=datetime.now(timezone.utc).isoformat(),
                project=payload.get('project_name', ''), sprint=payload.get('sprint', ''),
                payload=payload)


def export_history_bytes(store):
    records = []
    if isinstance(store, tuple):
        for record in store[1]:
            records.append(dict(id=record['id'], saved_at=record['saved_at'],
                                project=record.get('project', ''), sprint=record.get('sprint', ''),
                                payload=record.get('payload')))
    else:
        with history_connection(store) as connection:
            rows = connection.execute('SELECT id, saved_at, project, sprint, payload '
                                      'FROM snapshots ORDER BY saved_at').fetchall()
        records = [dict(id=row[0], saved_at=row[1], project=row[2], sprint=row[3],
                        payload=json.loads(row[4])) for row in rows]
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('qahub-history.json', json.dumps(
            dict(format=HISTORY_FORMAT, version=1, app='QAhub', snapshots=records),
            ensure_ascii=False))
    return buffer.getvalue()


def import_history_bytes(data):
    if isinstance(data, str):
        data = data.encode()
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            content = archive.read('qahub-history.json')
    except (zipfile.BadZipFile, KeyError) as exc:
        raise ValueError('Este arquivo não é um histórico do QAhub (.qahub).') from exc
    try:
        document = json.loads(content)
        if document.get('format') != HISTORY_FORMAT:
            raise ValueError('formato desconhecido')
        records = document.get('snapshots')
        if not isinstance(records, list):
            raise ValueError('lista de versões ausente')
        cleaned = []
        for record in records:
            if not isinstance(record, dict) or not record.get('id') \
                    or not isinstance(record.get('payload'), dict):
                raise ValueError('versão inválida dentro do arquivo')
            cleaned.append(dict(id=str(record['id']), saved_at=str(record.get('saved_at', '')),
                                project=str(record.get('project', '')),
                                sprint=str(record.get('sprint', '')),
                                payload=record['payload']))
    except (json.JSONDecodeError, TypeError, AttributeError) as exc:
        raise ValueError('Arquivo de histórico inválido ou corrompido.') from exc
    return cleaned


def merge_snapshots(store, records):
    # Importa sem duplicar: versões com o mesmo id já presentes são ignoradas.
    known = {entry['id'] for entry in list_snapshots(store)}
    added = 0
    for record in records:
        if record['id'] in known:
            continue
        if isinstance(store, tuple):
            store[1].append(record)
        else:
            with history_connection(store) as connection:
                connection.execute('INSERT INTO snapshots VALUES (?, ?, ?, ?, ?)',
                                   (record['id'], record['saved_at'], record['project'],
                                    record['sprint'],
                                    json.dumps(record['payload'], ensure_ascii=False)))
        known.add(record['id'])
        added += 1
    return added



